export const MLGG_DEFAULT_CARD = {"100":100201,"101":101201,"102":102201,"103":103201,"104":104201,"105":105301,"106":106301,"107":107301,"108":108301,"109":109301,"110":110301,"111":111301,"112":112301,"113":113301,"114":114301,"115":115301,"116":116301,"117":117301,"118":118301,"119":119301,"120":120301,"121":121301,"122":122201,"123":123201,"124":124201,"125":125101,"126":126101,"127":127101,"128":128101};

// Resolve a skill description at a skill level: picks the last description
// template unlocked at that level and substitutes ['spd', 2, [[1, 40.0], [3, 42.0], [4, 46.0], [6, 48.0], [7, 52.0], [9, 54.0], [10, 75.0]]] tokens.
export function mlggResolveSkill(card, skillIndex, level) {
  const skill = card.skills[skillIndex];
  let desc = skill.descs.length ? skill.descs[0][1] : "";
  for (const [lv, tpl] of skill.descs) {
    if (lv <= level) desc = tpl;
  }
  return desc.replace(/\{([^}]+)\}/g, (all, name) => {
    const tag = skill.tags[name];
    if (!tag) return all;
    const v = mlggInterpolate(tag, level);
    if (v === null) return all;
    return Number.isInteger(v) ? String(v) : v.toFixed(1);
  });
}

function tagPoints(tag, level) {
  const pts = tag.v;
  if (pts.length === 1) return pts[0];
  if (level <= pts[0][0]) return pts[0];
  if (level >= pts[pts.length - 1][0]) return pts[pts.length - 1];
  for (let i = 0; i < pts.length - 1; i++) {
    const [la, va] = pts[i], [lb, vb] = pts[i + 1];
    if (level >= la && level <= lb) return [la, va, lb, vb];
  }
  return pts[0];
}

export function mlggInterpolate(tag, level) {
  const p = tagPoints(tag, level);
  if (p.length === 2) return p[1];
  const [la, va, lb, vb] = p;
  if (tag.m === 1) return va;          // Fixed
  if (tag.m === 3) return va;          // Stepped (holds until next point)
  const t = (level - la) / Math.max(lb - la, 1);
  return va + (vb - va) * t;           // Linear
}

// Stat at a given level (1..200) and rarity (default..maxRarity), including
// cumulative limit-break bonuses. Returns flat stats; crit is in percent.
export function mlggStatAt(card, level, rarity) {
  const amt = MLGG_LERP[Math.min(Math.max(level, 1), MLGG_LEVEL_CAP) - 1];
  const up = card.rarityUp.find(r => r.rarity === rarity);
  const out = {};
  for (const k of ["hp", "atk", "def", "spd", "crit"]) {
    const base = card.min[k] + (card.max[k] - card.min[k]) * amt;
    const bonus = up ? (up[k] || 0) : 0;
    out[k] = k === "crit" ? Math.round((base + bonus) * 10) / 10 : Math.round(base + bonus);
  }
  return out;
}
